  function shortcuts(e:React.KeyboardEvent){
    if(e.key==='Escape'){const popup=root.current?.querySelector<HTMLDetailsElement>('.ps-filter-popover[open]');if(popup){popup.open=false;(filterTrigger.current||popup.querySelector<HTMLElement>('summary'))?.focus();e.preventDefault();e.stopPropagation();return;}}
    if(e.defaultPrevented||modal||(e.target as HTMLElement).closest('input,textarea,select,[contenteditable=true]')||e.metaKey||e.ctrlKey||e.altKey)return;
    const key=e.key.toLowerCase();if(e.shiftKey&&(key==='e'||key==='a'))return;let handled=true;
    if(/^[0-5]$/.test(key))void updateSelected(a=>({...a,rating:Number(key)}));else if(['z','u','x'].includes(key))void updateSelected(a=>({...a,flag:key==='z'?'pick':key==='x'?'reject':'none'}));
    else if(key==='e')selectTool('edit');else if(key==='c')selectTool('crop');else if(key==='h')selectTool('retouch');else if(key==='i')selectTool('info');else if(key==='k')openNamed('keywords',active?.keywords.join(', ')||'');else if(key==='j')setClipping(v=>!v);else if(key==='w'){selectTool('edit');setSampler(true);}else if(key==='l'||key==='r'||key==='b'){selectTool('mask');addMask(key==='l'?'linear':key==='r'?'radial':'brush');}else if(key==='o')setMaskOverlay(v=>!v);
    else if(['arrowleft','arrowright'].includes(key)&&photos.length){const index=photos.findIndex(a=>a.id===active?.id);choose(photos[clamp(index+(key==='arrowright'?1:-1),0,photos.length-1)]);}
    else if(key==='delete'||key==='backspace')moveToTrash();else if(key==='escape'){setBefore(false);setSampler(false);setPresetPreview(null);}else handled=false;
    if(handled){e.preventDefault();e.stopPropagation();}
  }
